void __send_blank_cmd_to_ppu(){
    uint32_t cmd_type= UINT32_C(0x50000000);//0x3<<28
    uint32_t rs1=cmd_type;
    uint32_t rs2=0;
    asm volatile (
        ".insn r 0x2B, 0x0, 0x00, x0, %0, %1"
        :
        : "r"(rs1), "r"(rs2)
        : "memory"
    );
}
void ppu_wait_nmi(){
     asm volatile (
        ".insn r 0x2B, 0x1, 0x00, x0, x0, x0"
